// Per-mechanic colours for the atlas wheels.
//
// Generated by tools/gen-palette.mjs: the mechanics whose colour the game already
// taught players are pinned (Blight green, Delve azurite, Exarch fire), the rest
// are solved for so no two wheels look alike. Don't hand-edit an entry without
// rerunning tools/check-palette.mjs — the closest pair is only ΔE 19 apart, so
// there is no slack for a stray nudge.

export const CATEGORY_COLOR = {
  "Abyss":                "#6b4fc4",
  "Atlas Memories":       "#9489bd",
  "Bestiary":             "#e08a3c",
  "Betrayal":             "#d0455f",
  "Beyond":               "#c92c95",
  "Blight":               "#4fc47a",
  "Breach":               "#c05ce6",
  "Conquerors":           "#2ca9c9",
  "Delirium":             "#f0aede",
  "Delve":                "#3f8fe0",
  "Divination Cards":     "#96824a",
  "Essence":              "#6268bc",
  "Expedition":           "#b8a528",
  "Harvest":              "#a8d44a",
  "Heist":                "#439d85",
  "Incursion":            "#9ee5bf",
  "Labyrinth":            "#e5968a",
  "Legion":               "#efe3b0",
  "Maps":                 "#a45f3d",
  "Mercenaries":          "#dab6a9",
  "Ritual":               "#9d586f",
  "Rogue Exiles":         "#d33636",
  "Scarabs":              "#c8bb6a",
  "Settlers of Kalguur":  "#517690",
  "Shrines":              "#84bec2",
  "Strongboxes":          "#d8a06e",
  "Synthesis":            "#8ab5e5",
  "The Eater of Worlds":  "#7a3f8f",
  "The Searing Exarch":   "#f05a2f",
  "The Shaper and Elder": "#c9d8e8",
  "Torment":              "#c18ae5",
  "Ultimatum":            "#9d9d9d",
  "Vaal Side Areas":      "#5f9c33",
};

// Uncategorised nodes (travel lines, voidstone downsides, gateways).
const NEUTRAL = { small: "#5a6673", notable: "#c9a35c", keystone: "#7fb8a8", wormhole: "#9a7fd0", root: "#e8ded0" };

const BG = [0x12, 0x16, 0x1c];

function hex(c) {
  return [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)];
}
function toHex([r, g, b]) {
  return "#" + [r, g, b].map((v) => Math.round(Math.min(255, Math.max(0, v))).toString(16).padStart(2, "0")).join("");
}
function mix(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

// Rank shading: smalls sink toward the background so the wheel reads as a
// gradient with its notables and keystone on top, all in the same hue.
const SHADE = { small: -0.42, notable: 0, keystone: 0.3, wormhole: 0, root: 0 };

const cache = new Map();

export function nodeColor(category, type) {
  if (!category || !CATEGORY_COLOR[category]) return NEUTRAL[type] || NEUTRAL.small;
  if (type === "wormhole" || type === "root") return NEUTRAL[type];
  const key = category + "|" + type;
  let c = cache.get(key);
  if (c) return c;
  const base = hex(CATEGORY_COLOR[category]);
  const t = SHADE[type] || 0;
  c = toHex(t < 0 ? mix(base, BG, -t) : mix(base, [255, 255, 255], t));
  cache.set(key, c);
  return c;
}

export function categoryColor(category) {
  return CATEGORY_COLOR[category] || NEUTRAL.notable;
}
